 useEffect(()=>{let cancelled=false;try{const request=indexedDB.open("nexora-voice-library",1);request.onupgradeneeded=()=>{const db=request.result;if(!db.objectStoreNames.contains("voices"))db.createObjectStore("voices",{keyPath:"id"});};request.onsuccess=()=>{const db=request.result;const tx=db.transaction("voices","readonly");const get=tx.objectStore("voices").getAll();get.onsuccess=()=>{if(!cancelled&&Array.isArray(get.result)){setVoiceLibrary(get.result);const first=get.result[0];if(first&&!videoVoiceReference)setVideoVoiceReference({name:first.name,dataUrl:first.dataUrl});}};};}catch{}return()=>{cancelled=true};},[]);
 const persistImportedVoice=async(file:File)=>{if(!file.type.startsWith("audio/"))throw new Error("Choose an audio file for a voice sample.");if(file.size>5_000_000)throw new Error("Voice samples must be 5 MB or smaller.");const sample=await readReferenceFile(file,5_000_000);const voice={id:crypto.randomUUID(),name:customVoiceName.trim()||file.name.replace(/\\.[^.]+$/,""),filename:file.name,dataUrl:sample.dataUrl,createdAt:new Date().toISOString()};await new Promise<void>((resolve,reject)=>{const request=indexedDB.open("nexora-voice-library",1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains("voices"))request.result.createObjectStore("voices",{keyPath:"id"});};request.onerror=()=>reject(new Error("Could not open local voice library."));request.onsuccess=()=>{const db=request.result;const tx=db.transaction("voices","readwrite");tx.objectStore("voices").put(voice);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>reject(new Error("Could not save voice sample to this browser."));};});setVoiceLibrary(items=>[voice,...items.filter(x=>x.id!==voice.id)]);setVideoVoiceReference({name:voice.name,dataUrl:voice.dataUrl});setCustomVoiceName(voice.name);setStatus("Voice imported and saved in this browser's private Nexora voice library.");};
